#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
if [[ "${1:---dry-run}" != "--operator" ]]; then
  printf '%s\n' 'LT-154 operator preparation only. No network, credentials or files are used.' \
    'Stages: vendor contract; exact disposable target + credential FILE; baseline;' \
    'accepted apply/restore; stale apply/restore; observed same-timestamp tests;' \
    'safe cleanup and sanitized evidence export. Maximum12 mutation attempts.' \
    "Use --operator only under Johnny's exact authorization; production hold stays."
  return 0
fi
TOTAL_STAGES=7
ENV_FILE=/dev/null
banner "CXone disposable-page canary — operator only"
warn "Passing finite trials cannot prove atomicity. This records a manual procedure; it sends no requests."
confirm "Do you have Johnny's explicit approval for this exact canary, evidence and cleanup?" || return 1
umask 077
stage "Current vendor contract"
say "Read docs/release/lt-154-vendor-questions.md and the vendor's current written answer."
say "Do not substitute archived timestamp docs or previous successful trials."
open_url "https://expert-help.nice.com/Integrations_and_Extending_Content/API"
ask CONTRACT_FILE "Absolute path of the approved vendor contract/evidence file:"
[[ "$CONTRACT_FILE" == /* && -f "$CONTRACT_FILE" && ! -L "$CONTRACT_FILE" ]] || return 1
confirm "Does that contract specify every-revision atomic comparison, rejection and finalization?" || return 1

stage "Exact disposable target and existing credential file"
ask CANARY_HOST "Exact approved host (dev.libretexts.org):"
ask CANARY_PAGE_ID "Exact approved numeric disposable page ID:"
ask CANARY_PATH "Exact approved disposable path under Sandboxes/johnnyphung/:"
ask CREDENTIAL_FILE "Absolute path of existing restricted credential FILE (no contents):"
[[ "$CANARY_HOST" == dev.libretexts.org && "$CANARY_PAGE_ID" =~ ^[1-9][0-9]*$ && "$CANARY_PATH" == Sandboxes/johnnyphung/* ]] || return 1
[[ "$CREDENTIAL_FILE" == /* && -f "$CREDENTIAL_FILE" && ! -L "$CREDENTIAL_FILE" ]] || return 1
say "The wizard never reads, prints or stores credential contents. Do not paste passwords/tokens."
ask CANARY_DIRECTORY "New absolute restricted evidence directory (must not exist):"
[[ "$CANARY_DIRECTORY" == /* && ! -e "$CANARY_DIRECTORY" && ! -L "$CANARY_DIRECTORY" ]] || return 1
confirm "Confirm exact host/pageID/path, synthetic-only content and at most12 attempts including cleanup" || return 1
mkdir -m 700 "$CANARY_DIRECTORY"
ENV_FILE="$CANARY_DIRECTORY/canary.env"
write_env CONTRACT_FILE "$CONTRACT_FILE"
write_env CANARY_HOST "$CANARY_HOST"
write_env CANARY_PAGE_ID "$CANARY_PAGE_ID"
write_env CANARY_PATH "$CANARY_PATH"
write_env CREDENTIAL_FILE "$CREDENTIAL_FILE"
write_env MUTATION_ATTEMPTS "0"
write_env OPERATOR_STARTED_UTC "$(date -u +%FT%TZ)"

stage "Baseline snapshot and identity"
say "Using your approved client and credential file, GET exact identity, synthetic body, revision and precondition."
say "Preserve matching body/token, SHA-256, raw timestamp precision, SDK/server versions and revision history."
say "Save restricted baseline bytes and sanitized evidence in the new directory. No request commands are invented here."
confirm "Do pageID/path match, with no foreign content/editor or unsettled request, and baseline saved?" || return 1

stage "Accepted apply and restore controls"
manual_attempt "Accepted apply A to synthetic B with the contract's captured A precondition" success
manual_attempt "Accepted restore B to saved baseline A using the contract's current B precondition" success

stage "Stale apply and stale restore"
manual_attempt "Independent synthetic A to B edit; preserve the old A precondition and known B revision" success
manual_attempt "Stale apply C using old A precondition; B and its revision must remain untouched" rejection
manual_attempt "Restore known B to A with current B precondition; preserve new A metadata" success
manual_attempt "Independent synthetic A to B edit for the stale-restore control" success
manual_attempt "Stale restore using old A precondition; B and its revision must remain untouched" rejection
manual_attempt "Restore known B to A with current B precondition; save matching A body/token/time" success

stage "Observed same-timestamp apply and restore"
say "One collision attempt is reserved. Never fabricate a timestamp or loop until one collides."
manual_attempt "Independent synthetic A to B edit; compare actual raw server timestamps for distinct revisions" success
if confirm "Do distinct observed A/B revisions share the exact accepted server timestamp?"; then
  manual_attempt "Stale same-timestamp apply using A precondition; B/revision must remain untouched" rejection
  manual_attempt "Stale same-timestamp restore using A precondition; B/revision must remain untouched" rejection
else
  write_env SAME_TIMESTAMP_RESULT "untested_no_observed_collision"
  say "Record same-timestamp behavior as UNTESTED. Do not spend further attempts seeking a collision."
fi

stage "Safe cleanup and sanitized export"
say "GET current body/revision first. Cleanup requires the latest known revision belongs to this trial."
confirm "Is cleanup explicitly authorized, with no foreign edit or unknown request, and identity still exact?" || return 1
manual_attempt "Restore saved baseline as a NEW revision using the contract's current precondition" success
say "Verify baseline hash, current revision and history by GET; preserve snapshots/audits/attempt log."
say "Copy a sanitized evidence summary for review; omit headers, credentials and private page content."
say "Do not delete the page, history, snapshots or evidence. Do not re-run to replay/resume attempts."
write_env OPERATOR_FINISHED_UTC "$(date -u +%FT%TZ)"
warn "Canary observations are candidate evidence only. Production hold remains; no deployment is authorized."
finish
}

manual_attempt() {
  local description="$1" expected="$2" outcome
  [[ "$MUTATION_ATTEMPTS" =~ ^[0-9]+$ && "$MUTATION_ATTEMPTS" -lt 12 ]] || { warn "Mutation budget exhausted. Stop."; return 1; }
  say "$description"
  say "Use the vendor-approved exact request. Redirects/retries disabled; one bounded attempt, no automation."
  confirm "Authorize and perform exactly ONE attempt now, after reserving it in the log?" || return 1
  write_env MUTATION_ATTEMPTS "$((MUTATION_ATTEMPTS + 1))"
  # Reservation precedes the human action. The user performs it only after this pause.
  pause "Now perform that one request, preserve status/body/revision/history, then press Enter."
  ask outcome "Verified outcome: success / rejection / unknown / foreign / failed:"
  printf '%s\t%s\t%s\t%s\n' "$MUTATION_ATTEMPTS" "$(date -u +%FT%TZ)" "$expected" "$outcome" >> "$CANARY_DIRECTORY/attempts.tsv"
  [[ "$outcome" == "$expected" ]] || { warn "STOP: preserve evidence; no retry or cleanup after unknown/foreign/unexpected outcome."; return 1; }
}

run_wizard "$@"; exit
